import torch

def run(x, dim, index, src, reduce):
    return x.scatter_reduce_(dim, index, src, reduce=reduce)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    dim = ctx["dim"]
    input_shape = ctx["x__shape"]
    return {
        "index": torch.randint(
            0,
            input_shape[dim],
            ctx["index__shape"],
            dtype=_dtype_from_context(ctx, "index"),
            device=device,
        )
    }
